verses.tafsir:
{ده‌ركردنى جوله‌كه‌كانى (به‌نى نه‌زیر)}
 [ <span class="arabic uthmani">هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ مِنْ دِيَارِهِمْ لِأَوَّلِ الْحَشْرِ</span> ] خوای گه‌وره‌ ئه‌و خوایه‌یه‌ كه‌ كافرانی ئه‌هلی كتابی له‌ ماڵی خۆیان ده‌ركرد بۆ سه‌ره‌تای حه‌شر، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  له‌ مه‌دینه‌ به‌ڵێننامه‌و په‌یماننامه‌ی له‌گه‌ڵدا نووسین كه‌ پیلان نه‌گێڕن دژی پێغه‌مبه‌ری خواو - <span class="saw">صلی الله علیه وسلم</span> -  موسڵمانان، به‌ڵام ئه‌وان په‌یمانه‌كه‌یان شكاندو به‌رده‌وام له‌ پیلانگێڕاندا بوون، وه‌ هه‌وڵی كوشتنی پێغه‌مبه‌ری خوایاندا - <span class="saw">صلی الله علیه وسلم</span> -  كه‌ پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  له‌گه‌ڵ ئیمامى (ئه‌بو به‌كرو عومه‌رو عه‌لى) رۆیشت بۆ لاى (به‌نی نه‌زیر) تا هاوكارى بكه‌ن له‌ خوێنى دوو كه‌س كه‌ موسڵمانێك به‌ هه‌ڵه‌ كوشتبوونى و هاوپه‌یمان بوون له‌گه‌ڵ (به‌نی نه‌زیر) پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  له‌ پاڵ دیوارێك دانیشتبوو وتیان هه‌رگیز هه‌لى وامان بۆ ناڕه‌خسێت كێ ده‌چێته‌ سه‌ره‌وه‌و به‌ردێكى گه‌وره‌ به‌ربداته‌وه‌ بان سه‌رى و له‌ كۆڵمانى بكاته‌وه‌؟ (عه‌مرى كوڕى جه‌حشى كوڕى كه‌عب) وتى من ده‌چم، به‌ڵام خواى گه‌وره‌ ئاگادارى كرده‌وه‌ بۆیه‌ پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  ده‌ری كردن له‌ مه‌دینه‌، كه‌ له‌سه‌ره‌تادا ده‌ركران بۆ (خه‌یبه‌ر)، وه‌ دواتر له‌وێش ده‌ركران، ئیمامی عومه‌ریش دواتر ده‌ری كردن، یاخود وتراوه‌: (لِأَوَّلِ الْحَشْرِ) مه‌به‌ست پێی زه‌وی شامه‌ كه‌ شوێنی حه‌شر كردنی خه‌ڵكییه‌ له‌ ڕۆژی قیامه‌ت وه‌كو (ابن عه‌باس) (خوای لێ ڕازی بێت) فه‌رموویه‌تی [ <span class="arabic uthmani">مَا ظَنَنْتُمْ أَنْ يَخْرُجُوا</span> ] ئه‌ی موسڵمانان ئێوه‌ گومانی ئه‌وه‌تان نه‌ئه‌برد (به‌نی نه‌زیر) به‌و ئاسانییه‌ له‌ شوێنی خۆیان ده‌رچن له‌به‌ر ئه‌وه‌ی قه‌ڵاو شورای زۆر پته‌و و به‌هێزیان هه‌بووه‌، وه‌ دار خورمای زۆریان هه‌بوو خانووی چاكیان هه‌بوو وه‌ ژماره‌یان زۆر بوو، وه‌ كه‌ره‌سته‌و ئامێره‌كانی جه‌نگیان زۆر بوو، گومانتان نه‌برد كه‌ به‌ ئاسانی ئاوا ماڵ و حاڵی خۆیان به‌جێ بێلن و به‌سه‌ریاندا زاڵ بن [ <span class="arabic uthmani">وَظَنُّوا أَنَّهُمْ مَانِعَتُهُمْ حُصُونُهُمْ مِنَ اللَّهِ</span> ] وه‌ ئه‌وانیش خۆیان گومانی وایان ئه‌برد كه‌ ئه‌و قه‌ڵاو شورا پته‌و و به‌هێزانه‌ ئه‌یانپارێزێ له‌ سزای خوای گه‌وره‌، به‌ڵام نه‌یپاراستن [ <span class="arabic uthmani">فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا</span> ] وه‌ فه‌رمانی خوای گه‌وره‌یان بۆ هات به‌ شێوازێك كه‌ به‌ خه‌یاڵیاندا نه‌هاتبوو كه‌ خوای گه‌وره‌ ترسی خسته‌ دڵیانه‌وه‌و ته‌سلیمی فه‌رمانی پێغه‌مبه‌ری خوا بوون - <span class="saw">صلی الله علیه وسلم</span> -  
{ خوای گه‌وره‌ ترس ده‌خاته‌ دڵی كافرانه‌وه‌}
[ <span class="arabic uthmani">وَقَذَفَ فِي قُلُوبِهِمُ الرُّعْبَ</span> ] وه‌ خوای گه‌وره‌ ترسی خسته‌ دڵیانه‌وه‌، پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  ده‌فه‌رمێت: (خواى گه‌وره‌ سه‌ریخستووم به‌سه‌ر دوژمندا له‌ دوورى مانگه‌ رێیه‌كه‌وه‌ ترس ده‌خاته‌ دڵیانه‌وه‌) [ <span class="arabic uthmani">يُخْرِبُونَ بُيُوتَهُمْ بِأَيْدِيهِمْ وَأَيْدِي الْمُؤْمِنِينَ</span> ] به‌ده‌ستی خۆیان و به‌ده‌ستی موسڵمانان ماڵی خۆیانیان ئه‌ڕوخاند، دوای ئه‌وه‌ی كه‌ ڕێككه‌وتن له‌سه‌ر ئه‌وه‌ی كه‌ ماڵی خۆیان به‌جێ بێلن ئه‌و كاته‌ ماڵه‌كانی خۆیان ئه‌ڕوخاندو داره‌كانیان ده‌رئه‌كرد له‌گه‌ڵ خۆیاندا ئه‌یانبرد بۆ ئه‌وه‌ی بۆ موسڵمانان نه‌بێ، وه‌ موسڵمانانیش له‌كاتى رووبه‌ڕووبوونه‌وه‌ ئه‌یانڕوخاند بۆ ئه‌وه‌ی كه‌ پێیان بگه‌ن [ <span class="arabic uthmani">فَاعْتَبِرُوا يَا أُولِي الْأَبْصَارِ (٢)</span> ] ئه‌ی ئه‌و كه‌سانه‌ی كه‌ خاوه‌ن بیناین و شت ئه‌بینن په‌ندو ئامۆژگاری وه‌ربگرن بزانن خوای گه‌وره‌ چی له‌ كه‌سانێك ئه‌كات كه‌ غه‌درو خیانه‌ت و ناپاكی بكه‌ن.

[ <span class="arabic uthmani">فَإِذَا بَلَغْنَ أَجَلَهُنَّ</span> ] وه‌ كاتێك كه‌ ئافره‌تان نزیك بوو عیدده‌كه‌یان ته‌واو بێت و سێ جار كه‌وتنه‌ سووڕی مانگانه‌وه‌ [ <span class="arabic uthmani">فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ</span> ] یان ئه‌وه‌تا بیانگه‌ڕێننه‌وه‌ به‌ڵام به‌ چاكه‌ به‌بێ ئه‌وه‌ی كه‌ زیانی پێ بگه‌یه‌نی، یان ئه‌گه‌ر ویستت هه‌ر به‌یه‌كجاری لێى جیابیته‌وه‌ ئه‌وه‌ به‌ چاكه‌ لێی جیابه‌ره‌وه‌ به‌وه‌ی كه‌ مافه‌كانی هه‌مووی پێ بده‌ی، نه‌ك بگاته‌ كۆتایی ئه‌وه‌ی كه‌ عیدده‌كه‌ی ته‌واو بێ دیسان بیهێنیته‌وه‌ بۆ ئه‌وه‌ی كه‌ زه‌ره‌رو زیانی پێ بگه‌یه‌نی، یان ده‌ستی لێ هه‌ڵگریت و ئازاری بده‌یت و جوێنى پێبده‌یت، یان مافه‌كانی پێ نه‌ده‌ی ئه‌مانه‌ حه‌رامه‌
{ ته‌لآقدان و هێنانه‌وه‌ پێویستى به‌ دوو شایه‌ته‌}
 [ <span class="arabic uthmani">وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ</span> ] وه‌ كاتێك كه‌ خێزانتان ته‌ڵاقدا با دوو كه‌سی دادپه‌روه‌ر شایه‌ت بن، وه‌ كه‌ هێناشتانه‌وه‌و موراجه‌عه‌شتان كردن با دوو كه‌سى دادپه‌روه‌ر شایه‌ت بن [ <span class="arabic uthmani">وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ</span> ] وه‌ شایه‌ته‌كانیش با له‌به‌ر خوای گه‌وره‌ ئه‌و شایه‌تییه‌ چۆنه‌ به‌ حه‌ق و دادپه‌روه‌ری شایه‌تییه‌كه‌ بده‌ن [ <span class="arabic uthmani">ذَلِكُمْ يُوعَظُ بِهِ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ</span> ] به‌م شێوازه‌ خوای گه‌وره‌ ئامۆژگاری ئه‌و كه‌سانه‌ ئه‌كات كه‌ باوه‌ڕیان به‌خواو به‌ڕۆژی دوایی هه‌یه‌ [ <span class="arabic uthmani">وَمَنْ يَتَّقِ اللَّهَ</span> ] وه‌ هه‌ر كه‌سێك ته‌قوای خوای گه‌وره‌ بكات به‌وه‌ی كه‌ سنووری خوای گه‌وره‌ نه‌به‌زێنێ و تاوان و سه‌رپێچی نه‌كات وه‌ خێزانه‌كه‌ی ته‌ڵاقدا له‌سه‌ر سوننه‌ت ته‌ڵاقی بدات، وه‌ گه‌ڕاندییه‌وه‌ له‌سه‌ر سوننه‌ت بیگه‌ڕێنێته‌وه‌، وه‌ شایه‌ت دابنێ [ <span class="arabic uthmani">يَجْعَلْ لَهُ مَخْرَجًا (٢)</span> ] ئه‌وه‌ خوای گه‌وره‌ ده‌رووی خێری لێ ئه‌كاته‌وه‌ له‌و كێشه‌یه‌ی كه‌ كه‌وتۆته‌ ناوی و ڕزگاری ئه‌كات، وه‌ له‌ ناخۆشییه‌كانى دونیاو قیامه‌ت رزگارى ده‌كات، یاخود كه‌وته‌ ناو هه‌ر شوبهه‌و گومانێك له‌ دیندا خوای گه‌وره‌ ده‌رووی لێ ئه‌كاته‌وه‌و ڕزگاری ئه‌كات، یاخود له‌سه‌ره‌مه‌رگدا له‌ ناخۆشییه‌كانی سه‌ره‌مه‌رگ ڕزگاری ئه‌كات، (ئیبنو مه‌سعود) ده‌فه‌رمێت: (گه‌وره‌ترین ئایه‌ت له‌ قورئاندا كه‌ كردنه‌وه‌ى ده‌روى خێرى تێدا بێت ئه‌م ئایه‌ته‌یه‌).

{عیدده‌ى ئه‌و ئافره‌تانه‌ى ناكه‌ونه‌ سوڕى مانگانه‌وه‌}
 [ <span class="arabic uthmani">وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ وَاللَّائِي لَمْ يَحِضْنَ</span> ] (ئوبه‌ى كوڕى كه‌عب) فه‌رمووى: ئه‌ى پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  عیدده‌ى چه‌ند ئافره‌تێك له‌ قورئاندا باس نه‌كراوه‌ وه‌كو ئه‌وانه‌ى كه‌م ته‌مه‌نن و نه‌كه‌وتونه‌ته‌ سوڕى مانگانه‌وه‌، وه‌ ئه‌وانه‌ى ته‌مه‌نیان گه‌وره‌یه‌و له‌سوڕى مانگانه‌ كه‌وتوونه‌، وه‌ ئه‌وانه‌ى دووگیانن، خواى گه‌وره‌ ئه‌م ئایه‌ته‌ى دابه‌زاند: وه‌ ئه‌و ئافره‌تانه‌ی كه‌ بێ ئومێد بوونه‌ له‌ كه‌وتنه‌ سووڕی مانگانه‌ له‌به‌ر گه‌وره‌یى ته‌مه‌نیان، وه‌ ئه‌وانه‌یشی كه‌ هێشتا كه‌م ته‌مه‌نن و نه‌كه‌وتوونه‌ته‌ سووڕی مانگانه‌وه‌، وه‌ ئێوه‌ گومانتان هه‌بوو له‌ عیدده‌كه‌یان و نه‌تانزانی عیدده‌یان چه‌نده‌ ئه‌وه‌ عیدده‌ی ئه‌وانه‌ سێ مانگه‌
  {عیدده‌ى ئافره‌تى دووگیان دانانى حه‌مله‌كه‌یه‌تى}
 [ <span class="arabic uthmani">وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ</span> ] به‌ڵام ئه‌گه‌ر ئافره‌ت ته‌ڵاقدرا یان مێرده‌كه‌ی مردو دووگیان بوون ئه‌و كاته‌ عیدده‌یان بریتییه‌ له‌ دانانی حه‌مله‌كه‌یان، هه‌ر كاتێك حه‌مله‌كه‌یان دانا ئه‌وه‌ عیدده‌كه‌یان كۆتایی هاتووه‌ ئه‌گه‌ر ته‌نها رۆژێكیش بێت [ <span class="arabic uthmani">وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا (٤)</span> ] وه‌ هه‌ر كه‌سێك ته‌قوای خوای گه‌وره‌ بكات و خۆی له‌ تاوان بپارێزێ ئه‌وا خوای گه‌وره‌ كاروباری له‌ دونیاو قیامه‌تدا بۆ ئاسان ئه‌كات، یان ته‌ڵاقدان و گه‌ڕاندنه‌وه‌و هێنانه‌وه‌ی خێزانه‌كه‌ی له‌سه‌ر سوننه‌ت بێ خوای گه‌وره‌ كاروباره‌كانی بۆ ئاسان ئه‌كات.

[ <span class="arabic uthmani">أَسْكِنُوهُنَّ مِنْ حَيْثُ سَكَنْتُمْ مِنْ وُجْدِكُمْ</span> ] ئافره‌ت كاتێك كه‌ ته‌ڵاقی (ره‌جعی) بوو ته‌ڵاقى یه‌كه‌م یان دووه‌م بوو مافی خۆیه‌تی له‌ ماڵدا بمێنێته‌وه‌و جێگیریان بكه‌ن له‌ ماڵه‌كانتان به‌ گوێره‌ی توانای خۆتان
{ئافره‌ت ناچار مه‌كه‌ن داواى ته‌ڵاق بكات}
 [ <span class="arabic uthmani">وَلَا تُضَارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ</span> ] به‌ڵام لێیان ته‌سك و ته‌نگ مه‌كه‌نه‌وه‌ له‌ نه‌فه‌قه‌دا یان له‌ جێگادا له‌ ماڵدا بۆ ئه‌وه‌ی كه‌ ناچار بن خۆیان داوای ته‌ڵاق بكه‌ن، یاخود ماڵ به‌جێ بهێلن یان بڵێ ماره‌یی و هیچم ناوێ ته‌نها ڕزگارم بێ له‌ ده‌ستی، یاخود لێ ته‌سك كردنه‌وه‌ بۆ ئه‌وه‌ی ته‌ڵاقی بدا ڕۆژێك دوو ڕۆژی مابێ و بیگه‌ڕێنێته‌وه‌ بۆ ئه‌وه‌ی ژیانی لێ تاڵ و ته‌سك بكات ئه‌مانه‌ هه‌مووی حه‌رامه‌و بێ ئه‌مری خوای گه‌وره‌یه‌ [ <span class="arabic uthmani">وَإِنْ كُنَّ أُولَاتِ حَمْلٍ</span> ] وه‌ ئه‌گه‌ر ته‌ڵاقه‌كه‌ ڕه‌جعی بوو (ته‌ڵاقى یه‌كه‌م یان دووه‌م) بوو ئه‌وه‌ گومانی تیادا نیه‌ ئافره‌ت نه‌فه‌قه‌و شوێن و جێگاى مانه‌وه‌ى هه‌یه‌، به‌ڵام ئه‌گه‌ر سێیه‌م ته‌ڵاق بوو ته‌ڵاقی (بائین) بوو نه‌ نه‌فه‌قه‌ی هه‌یه‌ نه‌ سوكناو شوێنی مانه‌وه‌ى هه‌یه‌، به‌ڵام ئه‌گه‌ر هاتوو ئافره‌ت حه‌ملی هه‌بوو ئه‌و كاته‌ خیلاف له‌ نێوان زاناكاندا هه‌یه‌ له‌سه‌ر ئه‌وه‌ی كه‌ ئایا واجبه‌ نه‌فه‌قه‌ی بكات یان نا [ <span class="arabic uthmani">فَأَنْفِقُوا عَلَيْهِنَّ حَتَّى يَضَعْنَ حَمْلَهُنَّ</span> ] به‌ڵام ته‌واوتر ئه‌وه‌یه‌ ئه‌گه‌ر ته‌ڵاقى (بائین)یش بوو دووگیان بوو پێویسته‌ له‌سه‌ری نه‌فه‌قه‌ی بكات تا حه‌مله‌كه‌ی دائه‌نێ و منداڵه‌كه‌ى ده‌بێت [ <span class="arabic uthmani">فَإِنْ أَرْضَعْنَ لَكُمْ فَآتُوهُنَّ أُجُورَهُنَّ</span> ] دوای ئه‌وه‌ی كه‌ منداڵه‌كه‌ی دانا ئه‌گه‌ر شیری به‌ منداڵه‌كه‌دا ئه‌بێ پیاوه‌كه‌ پاره‌ی ئه‌و شیره‌ بدات به‌ ئافره‌ته‌كه‌ كه‌ شیر به‌ منداڵی پیاوه‌كه‌ ئه‌دا، به‌ڵام سه‌ره‌تای شیره‌كه‌ كه‌ ژه‌گی پێ ئه‌ووترێ ئه‌وه‌ واجبه‌ له‌سه‌ر ئافره‌ت ئه‌وه‌ی بداتێ له‌به‌ر ئه‌وه‌ی سوودێكی زۆری بۆ منداڵ هه‌یه‌ [ <span class="arabic uthmani">وَأْتَمِرُوا بَيْنَكُمْ بِمَعْرُوفٍ</span> ] وه‌ ژن و پیاوه‌كه‌ كه‌ له‌ یه‌ك جیابوونه‌ته‌وه‌ با له‌ نێوان خۆیاندا به‌ چاكه‌ ڕاوێژ بكه‌ن، وه‌ ڕێك بكه‌ون له‌سه‌ر ئه‌وه‌ی كه‌ مانگانه‌ ئه‌و پیاوه‌ چه‌ندێك پاره‌ بدات به‌و ئافره‌ته‌ له‌سه‌ر ئه‌وه‌ی كه‌ شیر به‌ منداڵه‌كه‌ ئه‌دات [ <span class="arabic uthmani">وَإِنْ تَعَاسَرْتُمْ</span> ] وه‌ ئه‌گه‌ر هاتوو ڕێك نه‌كه‌وتن پیاوه‌كه‌ پاره‌یه‌كی كه‌می ئه‌داو ئافره‌ته‌كه‌ پێی ڕازی نه‌ئه‌بوو، یان ئافره‌ته‌كه‌ داوای زۆری ئه‌كردو پیاوه‌كه‌ بۆی نه‌ئه‌درا [ <span class="arabic uthmani">فَسَتُرْضِعُ لَهُ أُخْرَى (٦)</span> ] ئه‌وه‌ ئه‌و كاته‌ پیاوه‌كه‌ ئه‌توانێ منداڵه‌كه‌ وه‌ربگرێته‌وه‌و بیدات به‌ ئافره‌تێكی ترو ئافره‌تێكی تر به‌ كرێ بگرێ و شیر بدات به‌و منداڵه‌، به‌ڵام تا دایكی خۆی ڕێك بكه‌وێ له‌گه‌ڵیدا ئه‌و له‌ پێشتره‌ كه‌ شیر به‌ منداڵه‌كه‌ی خۆی بدات وه‌ پیاوه‌كه‌یش ئه‌بێ پاره‌و كرێی ئه‌و شیره‌ی بداتێ.
